<?php declare(strict_types=1);namespace App\Modules\SubcontractPayments\Services;use App\Core\Auth\Auth;use App\Core\Database\Database;use App\Core\Exceptions\BusinessRuleException;use App\Core\Support\Logger;use App\Modules\Accounting\Services\AccountingService;use App\Modules\SubcontractCertificates\Services\SubcontractCertificateService;use App\Modules\SubcontractPayments\DTOs\SubcontractPaymentData;use App\Modules\SubcontractPayments\DTOs\SubcontractPaymentTableQuery;use App\Modules\SubcontractPayments\Repositories\SubcontractPaymentRepository;use App\Shared\Numbering\NumberGeneratorService;final class SubcontractPaymentService{private const ELIGIBLE=['active','suspended','completed'];public function __construct(private readonly SubcontractPaymentRepository$payments,private readonly SubcontractCertificateService$certificates,private readonly NumberGeneratorService$numbers,private readonly Database$db,private readonly Auth$auth,private readonly Logger$logger,private readonly AccountingService$accounting){}public function subcontract(int$id):array{return$this->payments->subcontract($id)??throw new BusinessRuleException('عقد مقاول الباطن غير موجود.');}public function find(int$id):array{return$this->payments->find($id)??throw new BusinessRuleException('دفعة مقاول الباطن غير موجودة.');}public function paymentAccounts():array{return$this->payments->paymentAccounts();}public function save(SubcontractPaymentData$d,?int$id=null):int{return$this->db->transaction(function()use($d,$id){$s=$this->payments->subcontract($d->subcontractId,true)??throw new BusinessRuleException('عقد مقاول الباطن غير موجود.');$old=$id===null?null:$this->payments->find($id,true);if(!in_array($s['status'],self::ELIGIBLE,true))throw new BusinessRuleException('حالة العقد لا تسمح بإنشاء أو تعديل دفعة.');if($old!==null&&((int)$old['subcontract_id']!==$d->subcontractId||$old['status']!=='draft'))throw new BusinessRuleException('الدفعة غير قابلة للتعديل.');if(!$this->payments->paymentAccount($d->paymentAccountId,$d->paymentChannel))throw new BusinessRuleException('حساب الدفع غير نشط أو لا يتبع نوع الدفع المختار.');if($old!==null&&preg_match('/^SPAY-(\d{4})-/',(string)$old['payment_code'],$m)&&$m[1]!==substr($d->paymentDate,0,4))throw new BusinessRuleException('لا يمكن تغيير سنة تاريخ الدفعة. ألغِ المسودة وأنشئ دفعة جديدة.');if($id===null)return$this->payments->create($this->numbers->nextSubcontractPaymentCode((int)substr($d->paymentDate,0,4)),$d,$s,$this->user());$this->payments->update($id,$d);return$id;});}public function post(int$id):void{$this->db->transaction(function()use($id){$probe=$this->find($id);$s=$this->payments->subcontract((int)$probe['subcontract_id'],true)??throw new BusinessRuleException('العقد غير موجود.');$p=$this->payments->find($id,true)??throw new BusinessRuleException('الدفعة غير موجودة.');if($p['status']!=='draft')throw new BusinessRuleException('يمكن ترحيل مسودة الدفعة فقط.');if(!in_array($s['status'],self::ELIGIBLE,true))throw new BusinessRuleException('حالة العقد لا تسمح بترحيل الدفعة.');$account=$this->payments->paymentAccount((int)$p['payment_account_id'],(string)$p['payment_channel'],true)??throw new BusinessRuleException('حساب الدفع غير صالح للترحيل.');$latest=$this->payments->latestPosted((int)$s['id']);if($latest!==null&&$p['payment_date']<$latest['payment_date'])throw new BusinessRuleException('لا يمكن ترحيل دفعة بتاريخ أقدم من آخر دفعة مرحلة.');$earned=$this->certificates->getApprovedEarnedValue((int)$s['id']);$progress=$this->certificates->getApprovedProgressPercentage((int)$s['id']);$posted=$this->payments->postedTotal((int)$s['id']);$available=$this->payments->availability($earned,$posted);if((int)$available['inconsistent']===1)throw new BusinessRuleException('يوجد عدم اتساق مالي في سجل العقد.');if($this->payments->amountExceeds((string)$p['amount'],(string)$available['available']))throw new BusinessRuleException('مبلغ الدفعة يتجاوز المتاح للدفع.');$payable=$this->accounting->mappedAccount('subcontract_payable',true);$descript